-- Postulaciones nuevas (septiembre 2026): mismas preguntas que los formularios de Google.
-- Pégalo en Supabase > SQL Editor > Run. Solo cambia las preguntas (y el nombre de EPS Zura).

update public.facciones set preguntas = '[{"texto": "¿Conoces nuestras normativas generales?", "opciones": ["Sí", "No"]}, {"texto": "¿Has sido EMS antes?", "opciones": ["Sí", "No"]}, {"texto": "¿Eres consciente que al pertenecer a esta facción civil de EPS/EMS no puedes ser delictivo, banda o guerilla?", "opciones": ["Sí", "No"]}]'::jsonb, nombre = 'EPS Zura' where id = 'ems';
update public.facciones set preguntas = '[{"texto": "¿Conoces nuestras normativas generales?", "opciones": ["Sí", "No"]}, {"texto": "¿Conoces nuestras normativas legales y de la Policía Nacional de Colombia?", "opciones": ["Sí", "No"]}, {"texto": "¿Has sido policía antes?", "opciones": ["Sí", "No"]}]'::jsonb where id = 'policia';
update public.facciones set preguntas = '[{"texto": "¿Conoces nuestras normativas generales?", "opciones": ["Sí", "No"]}, {"texto": "¿Conoces nuestras normativas legales y del Ejército Nacional de Colombia?", "opciones": ["Sí", "No"]}, {"texto": "¿Has sido policía, guardia o de algún rol legal antes?", "opciones": ["Sí", "No"]}]'::jsonb where id = 'ejercito';
update public.facciones set preguntas = '[{"texto": "¿Conoces nuestras normativas generales?", "opciones": ["Sí", "No"]}, {"texto": "¿Has interpretado roles legales o de gobernación antes?", "opciones": ["Sí", "No"]}, {"texto": "¿Eres consciente que al pertenecer a esta facción civil de Fiscalía General de la Nación no puedes ser delictivo, banda o guerrilla?", "opciones": ["Sí", "No"]}, {"texto": "¿A qué puesto te quieres postular?", "opciones": ["Ministerio de Defensa", "Fiscal General", "Juez", "Director del CTI", "Investigador del CTI", "Agente del CTI", "Abogado"]}, {"texto": "¿Porqué quieres pertenecer a la Fiscalía General de la Nación y interpretar ese personaje?", "min": 6}]'::jsonb where id = 'fiscalia';
